const unique = new Set();
for (const item of topics) {
  if (unique.has(item.slug)) throw new Error(`Duplicate slug: ${item.slug}`);
  unique.add(item.slug);
}

const esc = (value) => value.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");
const fileName = (item) => `${item.slug}.md`;
const imageOne = (item) => `blog/${item.slug}-application.webp`;
const imageTwo = (item) => `blog/${item.slug}-inspection.webp`;

function sourceList(item) {
  const selected = item.compliance ? sources : sources.slice(0, 5);
  return selected.map(([label, url]) => `- [${label}](${url})`).join("\n");
}

function articleText(item, number) {
  const intro = `The direct answer is to buy ${item.product} against the real ${item.application}, not against a catalog photograph or a lowest-unit-price quote. A buyer should define ${item.dimension}, confirm the ${item.material}, run a production-representative ${item.test}, approve the ${item.packaging}, and keep a document file that covers ${item.doc}. This is the practical route for ${item.audience}. It also gives procurement, quality and operations one shared reference when the first quotation, sample and production lot are compared.`;
  const problem = `The commercial risk in this category is often hidden between departments. A purchasing team may see a familiar size, a marketing team may see a clean print, and a production team may discover that the item behaves differently once it meets the actual food, machine, storage room or service route. For ${item.application}, the important question is whether the finished item stays within the approved use from receiving through disposal. That means discussing the food or beverage, contact time, temperature, humidity, handling, pack opening and destination market before asking a supplier to quote. If any of those assumptions change, the sample and the documents need to be reconsidered rather than silently carried forward.`;
  const scope = `Start the RFQ with a one-page requirement sheet. State the product name, intended food or beverage, direct or indirect contact, service or cooking condition, target quantity, destination, artwork status, pack format and inspection expectation. Add the dimensions that control fit: ${item.dimension}. For a repeat order, attach the approved sample or drawing and identify which characteristics are critical to function, which are visual preferences and which are commercial options. This avoids a common sourcing error in which a supplier optimizes for an attractive sample while the buyer actually needs stable performance and repeatable carton control.`;
  const material = `Material language should be specific. Ask the supplier to identify the paper, coating, ink, adhesive or support components that make up the finished item and to connect that description to the approved SKU. A general statement such as food grade, natural, recyclable or safe is not a substitute for a product-specific use statement. In the EU, Regulation (EC) No 1935/2004 sets general expectations for materials intended to contact food, including avoiding transfer that could endanger health or cause an unacceptable change in composition or organoleptic characteristics. Regulation (EC) No 2023/2006 addresses good manufacturing practice. In the United States, FDA food-contact status depends on the substance and its intended use. Buyers should therefore ask which legal basis, food type, time and temperature assumptions the supplier used, then retain the limitation with the approval record.`;
  const table = `| Buyer control | What to specify or ask | Evidence to keep |\n| --- | --- | --- |\n| Fit and dimensions | ${item.dimension} | Approved drawing, sample measurements and revision code |\n| Material and use | ${item.material} | Product declaration and use limitations |\n| Application result | ${item.test} | Trial notes, photos, recipe or beverage details and disposition |\n| Packaging | ${item.packaging} | Pack specification, carton sample and receiving check |\n| Supplier control | ${item.doc} | Current documents, lot records and change notice terms |`;
  const application = `Do not approve the sample on a desk alone. Build a short application protocol using the buyer's actual ${item.application}. Record the supplier sample code, production date if available, food or beverage formula, equipment, temperature or storage condition, contact duration, operator, pack format and result. Inspect the item before use, during the critical step and after cooling, display, transport or service. Note release, odor, staining, deformation, tearing, count, fit, print set-off and customer-facing appearance as applicable. The objective is not to create an invented universal pass limit. It is to establish whether this specific construction performs against the buyer's own approved requirement and whether the result can be repeated with production-representative material.`;
  const trial = `A useful sequence is: receive and photograph the unopened sample; verify the label and count; measure the critical dimensions; run the agreed application with a control where practical; inspect the food-contact surface and the finished product; pack and move the result through the intended route; then compare the result with the approved drawing and commercial requirement. For ${item.product}, pay particular attention to ${item.test}. If the supplier sends a revised sample, record what changed and repeat the relevant part of the trial. A buyer should not let a visually similar substitute enter the approval file without a new identity check.`;
  const packaging = `Packaging is part of the product decision because the paper or accessory must reach the buyer in the same condition as the approved sample. Confirm ${item.packaging}. Ask how inner packs are sealed, how counts are controlled, where lot codes appear, how cartons are palletized and what storage conditions the supplier expects. On receipt, photograph the pallet before opening, reconcile carton and inner-pack counts, inspect edge and surface condition, and keep one carton label with the receiving record. Where the item is sensitive to humidity, compression, odor or dust, agree the storage window and handling route before shipment rather than discovering the limit at the customer's production line.`;
  const supplier = `Supplier comparison should use a weighted scorecard rather than a single quotation field. Score technical fit, application result, document quality, packaging, communication, corrective-action discipline and total landed risk. For this query, a supplier should be able to explain the approved construction, show how incoming and finished goods are checked, identify the records attached to a lot, and state how changes are communicated. A factory tour can be useful, but a tour is not a substitute for a controlled sample, a clear specification or evidence from the product being purchased. For ${item.audience}, the strongest supplier is the one that makes the buyer's own approval and repeat-order control easier.`;
  const inspection = `Before shipment, define an inspection plan in plain language. It can include identity, dimensions, appearance, print, count, carton condition, lot code and any application-specific checks. Do not insert a fixed AQL number or a guaranteed tolerance unless the buyer has agreed it with the supplier and the product drawing supports it. Instead, name the sample plan, the critical characteristics, the comparison standard and the disposition for a deviation. Keep photos of defects, measurements and the release decision. If an issue is found, quarantine the affected stock, identify the lot, preserve samples and request a root-cause and corrective-action response. This is more useful than accepting a general promise to improve.`;
  const checklist = `Use this release checklist:\n\n- Confirm the SKU, revision, material construction and approved sample.\n- Check ${item.dimension} against the current drawing or agreed reference.\n- Verify the food, beverage, equipment, storage or service assumptions used in approval.\n- Review the product-specific document file, revision date, limitations and lot link.\n- Inspect inner packs, counts, carton labels, pallet condition and storage instructions.\n- Record any deviation, hold or corrective action before the goods move into normal stock.`;
  const comparison = `When comparing quotations, separate the unit price from the cost of failure. Include tooling or artwork charges, sample and testing work, inner-pack and carton changes, freight cube, pallet utilization, receiving labor, likely scrap, line interruption, relabeling and the cost of repeating a sample. A more expensive construction can be the better commercial choice if it reduces unstable denesting, damaged presentation, customer complaints or rejected cartons, but that conclusion should come from the buyer's trial and records rather than an unsupported promise. Ask every supplier to quote the same approved specification and to list any assumption that is not included.`;
  const workflow = `A disciplined approval workflow is: (1) issue the requirement sheet; (2) collect comparable quotations and document lists; (3) receive samples with identity information; (4) inspect and test the samples in the real application; (5) resolve deviations; (6) sign the specification, artwork and pack-out; (7) approve the first production lot; and (8) monitor repeat shipments using retained samples and complaint records. That sequence is practical for global buyers because it keeps commercial, technical and compliance decisions connected. It also creates a clean handoff between sourcing, quality, production, warehouse and customer service.`;
  const faq = `## FAQ\n\n### What should a buyer send with an RFQ for ${item.product}?\nSend the intended use, food or beverage, destination, quantity, dimensions, artwork status, pack-out and the application conditions. For this category, include ${item.dimension}. A supplier cannot responsibly choose a construction from a product name alone.\n\n### Is a supplier declaration enough to approve the product?\nIt is one part of the file. Match the declaration to the finished sample, intended use, market and current revision, then complete the application and packaging checks that matter to the buyer. If the declaration has limitations, record them rather than treating it as a blanket certificate.\n\n### How many samples should be tested?\nUse enough production-representative pieces to observe normal variation and the buyer's actual process. The buyer should define the sample plan around the risk and the application, not accept an arbitrary number presented as universal. Keep representative retained samples from the approved lot.\n\n### What is the most important supplier question?\nAsk the supplier to explain how the approved construction is identified, inspected, packed and kept unchanged between the approved sample and repeat production. Then ask for records that support the answer.\n\n### Can LANGMAI quote this requirement?\nLANGMAI can review the product type, size, material, artwork, quantity, destination and sample route for the paper packaging categories in its range. Buyers should send the finished use case and document requirements so the quotation is based on an agreed specification rather than a generic catalog description.`;
  const conclusion = `The best purchase decision for ${item.keyword} is a documented fit decision. Define the use, approve the construction through a real sample, review the food-contact and traceability file, protect the item in transit and release repeat orders against the same reference. That process gives ${item.audience} a clearer basis for comparing suppliers and a practical way to contain problems if a shipment or application does not match the approved requirement.`;

  return `# Article ${number}\n\n## SEO Information\n\nSEO Title: ${item.title}\n\nH1: ${item.title}\n\nURL Slug: /resources/${item.slug}/\n\nMeta Description: ${esc(`Source ${item.keyword} with a practical buyer guide to specifications, samples, food-contact documents, packaging, inspection and supplier evaluation.`)}\n\nPrimary Keyword: ${item.keyword}\n\nTarget Keywords: ${item.keyword}, ${item.product} supplier, ${item.product} specification, ${item.product} sample testing, ${item.product} quality inspection\n\nSearch Intent: Commercial investigation, application selection, document review and supplier evaluation for ${item.audience}.\n\nPublish Date: ${item.date}\n\nImage 1 File: ${imageOne(item)}\n\nImage 2 File: ${imageTwo(item)}\n\n## Introduction\n\n${intro}\n\n${problem}\n\n## What Buyers Should Define Before Comparing Suppliers\n\n${scope}\n\n- Product and application: ${item.application}.\n- Critical fit: ${item.dimension}.\n- Construction: ${item.material}.\n- Sample method: ${item.test}.\n- Pack-out: ${item.packaging}.\n- Evidence: ${item.doc}.\n\n## Buyer Control Table\n\n${table}\n\n## Material, Food-Contact and Document Review\n\n${material}\n\n${item.compliance ? "Regulatory timing matters as well. The European Commission's 2026 guidance on Regulation (EU) 2025/40 explains that food-contact packaging placed on the EU market after 12 August 2026 must meet the applicable PFAS limits in Article 5(5), subject to the legal scope and other applicable Union rules. That is a current market requirement to verify against the finished packaging and its placing-on-the-market event, not a reason to publish a universal claim about every paper product. Buyers should ask suppliers to identify the exact product scope and evidence used." : "Where a current market claim is relevant, keep the claim narrower than the evidence. For example, a paper product can have a defined grease-resistant function without the buyer claiming a particular chemical, recycling route or certification that has not been documented for the finished item."}\n\nInternal review can be organized around four questions: Does the document identify the product? Does it state the intended food and conditions? Does it identify the legal or technical basis? Does it remain current for the supplier, factory and lot being purchased? If any answer is no, place the item in review rather than treating a logo or unsigned marketing paragraph as final approval.\n\n## Sample and Application Testing\n\n${application}\n\n${trial}\n\n## Packaging, Storage and Shipment\n\n${packaging}\n\n## How to Evaluate the Supplier\n\n${supplier}\n\n| Evaluation area | Buyer question | Practical evidence |\n| --- | --- | --- |\n| Technical fit | Can the supplier explain the critical characteristics? | Drawing, sample record and trial notes |\n| Repeatability | How is the same construction controlled in production? | Incoming and finished inspection records |\n| Documents | Are the files current and product-specific? | Declarations, reports and revision history |\n| Packaging | Will the approved condition survive shipment and storage? | Pack specification, carton sample and receiving check |\n| Recovery | What happens when a deviation is found? | Complaint route, corrective action and closure evidence |\n\n## Inspection and Release Checklist\n\n${inspection}\n\n${checklist}\n\nCTA button: Request a product-specific sample and quotation\n\n## Compare Quotes on Landed Risk, Not Unit Price Alone\n\n${comparison}\n\n## Approval and Repeat-Order Workflow\n\n${workflow}\n\n${faq}\n\n## Conclusion\n\n${conclusion}\n\n## CTA\n\nSend LANGMAI the product, size, material, quantity, destination, artwork status and application details. The team can review the requirement, suggest a sample route and identify the information needed for a quote-ready specification.\n\nCTA button: Send Your Requirements\n\n## Sources\n\n${sourceList(item)}\n\n## Image Plan and AI Prompts\n\n- Image 1 basis: ${item.scene1}. This supports the application and selection sections and should show the actual product, equipment or service environment with realistic material scale and no readable invented labels.\n- Image 2 basis: ${item.scene2}. This supports the inspection, documents and packaging sections and should show a distinct buyer or quality-review scene with real tools and no fake certificates, logos or parameters.\n`;
}

const startNumber = 1001;
topics.forEach((item, index) => {
  const target = path.join(outDir, fileName(item));
  if (fs.existsSync(target)) throw new Error(`Refusing to overwrite existing article: ${target}`);
  fs.writeFileSync(target, articleText(item, startNumber + index), "utf8");
});

fs.writeFileSync(path.join(root, "scripts", "langmai-backfill-image-manifest.json"), JSON.stringify(topics.map((item) => ({
  date: item.date,
  title: item.title,
  slug: item.slug,
  image1: imageOne(item),
  image2: imageTwo(item),
  prompt1: item.scene1,
  prompt2: item.scene2,
})), null, 2));

console.log(`Generated ${topics.length} LANGMAI backfill article sources and image manifest.`);
